import{z as l,x as A,o as e,c as p,q as o,j as t,D as r,d as B,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"密码破解","description":"","frontmatter":{"title":"密码破解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/password-cracking.md","filePath":"cs/password-cracking.md","lastUpdated":1791413859000}'),d={name:"cs/password-cracking.md"};function c(m,a,h,C,T,D){const s=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="密码破解" tabindex="-1">密码破解 <a class="header-anchor" href="#密码破解" aria-label="Permalink to &quot;密码破解&quot;">​</a></h1><div class="epigraph"><p>离线猜口令吃的是哈希与熵，不是登录框的速率限制。盐挡住预计算表，慢哈希挡住尝试速率；用户选的口令熵往往仍不够。</p><footer>—— 据 Morris and Thompson, Password Security, CACM 1979；NIST SP 800-63B；Provos and Mazières, bcrypt</footer></div><p>上一课<a href="/cs/totp-mfa">TOTP</a>假定第一因素仍常是口令。缺口是<strong>泄漏后的离线猜测</strong>：哈希库一旦出门，攻击者在自己的机器上试。本课讲防御参数，不提供字表或工具教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>明文存口令是事故。无盐哈希被彩虹表；快速哈希让 GPU 试亿次。缺口是：盐（每用户）、慢哈希（Argon2/bcrypt/scrypt）、禁止泄露的常见口令、MFA。不重写 HKDF——那是高熵 IKM。</p><p><span class="marginnote">「彩虹表」就是预先算好、压缩存盘的巨型『哈希→口令』对照表——用空间换时间的离线猜测。盐的作用一句话：给每个用户的口令加一段随机前缀再哈希，使同样的「123456」在不同账户里哈希值都不同，整张表一次性作废。</span></p><h3 id="在线与离线" tabindex="-1">在线与离线 <a class="header-anchor" href="#在线与离线" aria-label="Permalink to &quot;在线与离线&quot;">​</a></h3><p>登录接口要锁定与速率限制；那挡在线。泄漏库是离线，只能靠哈希造价与熵。</p><p><span class="marginnote">Morris–Thompson 1979。NIST 现鼓励长度与检查泄漏集，不强制定期轮换复杂规则。本课禁止破解作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照存储：明文 / 快哈希 / 盐+慢哈希。指出 pepper（服务器密钥）是额外，密钥仍要管。下一课生物识别：不可轮换的测量，不是口令。</p>',12)),(e(),t(n,null,{default:r(()=>[i(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PWD%5B%22%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20SALT%5B%22%E6%AF%8F%E7%94%A8%E6%88%B7%E7%9B%90%22%5D%0A%20%20SALT%20--%3E%20SLOW%5B%22%E6%85%A2%E5%93%88%E5%B8%8C%22%5D%0A%20%20SLOW%20--%3E%20STORE%5B%22%E5%8F%AA%E5%AD%98%E5%93%88%E5%B8%8C%22%5D%0A%20%20ENT%5B%22%E7%94%A8%E6%88%B7%E7%86%B5%22%5D%20--%3E%20COST%5B%22%E7%8C%9C%E6%B5%8B%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"身份单元里口令是共享秘密中最弱的常见形态。哈希参数是把离线猜测推进计算安全游戏。生物下一课把「测你是谁」的错误率写成 FAR/FRR。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：现代 GPU 对纯 MD5 每秒能试约百亿次；换成调到单次约 100 ms 的 Argon2，同一台机器每秒只剩 10 次——快了 9 个数量级。这就是「慢哈希」的全部含义：把猜测速率压到按年计，等用户改密码。")],-1)),(e(),t(n,null,{default:r(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E6%8B%BF%E5%88%B0%E6%B3%84%E6%BC%8F%E7%9A%84%E5%93%88%E5%B8%8C%E5%BA%93%22%5D%20--%3E%20Q%7B%22%E5%BA%93%E9%87%8C%E6%98%AF%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%98%8E%E6%96%87%22%20--%3E%20W0%5B%22%E7%9B%B4%E6%8E%A5%E8%AF%BB%E8%B5%B0%EF%BC%8C%E5%85%A8%E7%9B%98%E5%A4%B1%E5%AE%88%22%5D%0A%20%20Q%20--%20%22%E6%97%A0%E7%9B%90%E5%BF%AB%E5%93%88%E5%B8%8C%22%20--%3E%20W1%5B%22%E5%BD%A9%E8%99%B9%E8%A1%A8%20%2F%20GPU%20%E5%AD%97%E5%85%B8%E7%A7%92%E7%BA%A7%E6%89%AB%22%5D%0A%20%20Q%20--%20%22%E7%9B%90%20%2B%20%E6%85%A2%E5%93%88%E5%B8%8C%22%20--%3E%20W2%5B%22%E6%AF%8F%E7%94%A8%E6%88%B7%E5%8D%95%E7%8B%AC%E6%85%A2%E5%93%88%E5%B8%8C%E8%AF%95%E7%8C%9C%22%5D%0A%20%20W2%20--%3E%20W3%5B%22%E5%BC%B1%E5%8F%A3%E4%BB%A4%E4%BB%8D%E5%85%88%E5%80%92%E4%B8%8B%22%5D%0A%20%20W3%20--%3E%20W4%5B%22%E9%AB%98%E7%86%B5%E5%8F%A3%E4%BB%A4%EF%BC%9A%E4%BB%A3%E4%BB%B7%E6%8E%A8%E5%88%B0%E4%B8%8D%E5%8F%AF%E8%A1%8C%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>盐与 pepper 别混：盐明文存在同一张库里，唯一使命是让相同口令的哈希互不相同（顺带废掉彩虹表）；pepper 是不写进库、只活在服务器配置里的全局密钥——库泄了它还在，代价是多管好一把钥匙。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给 GPU 配置。生物识别 FAR/FRR 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MFA 之外，口令泄漏走离线猜测。</li><li>盐+慢哈希+拒绝常见口令。</li><li>在线速率限制管不了已泄漏的哈希库。</li><li>下一课生物识别错误率。</li><li>出处：Morris and Thompson, 1979；NIST SP 800-63B；Provos and Mazières, bcrypt。</li></ul>',5))])}const f=l(d,[["render",c]]);export{u as __pageData,f as default};
